using System;

namespace FunscriptToolbox.SubtitlesVerbs.Infra
{
    /// <summary>
    /// The engine of the steps in the main configuration (generated by the code): no engine yet. A step that sends an AI request
    /// with it waits for the user ('needs you'), until a real engine is chosen (ex. { "$ref": "AIEngineGemini3Pro" }).
    /// (a step that doesn't send requests with it, ex. a TransformManualInputPreparer with TimingRefineEngineNone, works)
    /// </summary>
    [ConfigDoc("No AI engine: the placeholder of the main configuration. A step that sends an AI request with it waits for you to choose a real engine ('needs you').",
        Advice = "Choose a real engine for the step (✎ on its 'Engine').")]
    public sealed class AIEngineNeedToBeOverriden : AIEngine
    {
        public override AIResponse[] Execute(
            SubtitleGeneratorContext context,
            AIRequest[] requests)
        {
            // (the user is asked to choose one: 'needs you', the button opens the Config tab on 'Engine')
            throw new NeedsUserException(
                "This step has no AI engine: its 'Engine' is still the placeholder of the main configuration (AIEngineNeedToBeOverriden). " +
                "Choose a real engine for the step (✎ on 'Engine' in the Config tab, or in an override file, ex. \"Engine\": { \"$ref\": \"AIEngineGemini3Pro\" }).",
                NeedsUserException.ConfigActionPrefix + "Engine");
        }
    }
}
